PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'agent', banned INTEGER NOT NULL DEFAULT 0, banReason TEXT, banExpires INTEGER);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, impersonatedBy TEXT);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_user ON account(userId);
CREATE UNIQUE INDEX account_provider_identity ON account(providerId, accountId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE processes (id TEXT PRIMARY KEY, name TEXT NOT NULL, client TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE TABLE trainer_processes (user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, process_id TEXT NOT NULL REFERENCES processes(id) ON DELETE CASCADE, PRIMARY KEY(user_id, process_id));
CREATE TABLE batches (id TEXT PRIMARY KEY, name TEXT NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), created_at INTEGER NOT NULL);
CREATE TABLE batch_members (batch_id TEXT NOT NULL REFERENCES batches(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, PRIMARY KEY(batch_id, user_id));
CREATE TABLE assets (id TEXT PRIMARY KEY, process_id TEXT NOT NULL REFERENCES processes(id), object_key TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, name TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL);
CREATE TABLE scenarios (id TEXT PRIMARY KEY, process_id TEXT NOT NULL REFERENCES processes(id), title TEXT NOT NULL, office TEXT NOT NULL CHECK(office IN ('front','back')), draft_json TEXT NOT NULL, draft_revision INTEGER NOT NULL DEFAULT 1, published_version INTEGER, created_by TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE scenario_versions (id TEXT PRIMARY KEY, scenario_id TEXT NOT NULL REFERENCES scenarios(id), version INTEGER NOT NULL, content_json TEXT NOT NULL, published_by TEXT NOT NULL REFERENCES user(id), published_at INTEGER NOT NULL, UNIQUE(scenario_id, version));
CREATE TABLE assignments (id TEXT PRIMARY KEY, scenario_version_id TEXT NOT NULL REFERENCES scenario_versions(id), user_id TEXT NOT NULL REFERENCES user(id), batch_id TEXT REFERENCES batches(id), channels_json TEXT NOT NULL, assigned_by TEXT NOT NULL REFERENCES user(id), assigned_at INTEGER NOT NULL);
CREATE INDEX assignment_user ON assignments(user_id);
CREATE TABLE attempts (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), user_id TEXT NOT NULL REFERENCES user(id), mode TEXT NOT NULL CHECK(mode IN ('walkthrough','practice','assessment')), channel TEXT NOT NULL CHECK(channel IN ('workflow','chat','voice')), status TEXT NOT NULL CHECK(status IN ('active','submitted','approved','retry')), current_step INTEGER NOT NULL DEFAULT 0, result_json TEXT, started_at INTEGER NOT NULL, submitted_at INTEGER, reviewed_at INTEGER, reviewed_by TEXT REFERENCES user(id), review_note TEXT, operation_token TEXT, operation_started_at INTEGER);
CREATE INDEX attempt_assignment ON attempts(assignment_id,user_id);
CREATE TABLE action_events (id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), request_id TEXT NOT NULL, step_id TEXT NOT NULL, hotspot_id TEXT, value TEXT, correct INTEGER NOT NULL, critical INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(attempt_id,request_id));
CREATE TABLE turns (id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), request_id TEXT NOT NULL, sequence INTEGER NOT NULL, agent_text TEXT NOT NULL, customer_text TEXT, state TEXT NOT NULL CHECK(state IN ('pending','completed','failed')), created_at INTEGER NOT NULL, UNIQUE(attempt_id,request_id), UNIQUE(attempt_id,sequence));
CREATE TABLE operation_receipts (attempt_id TEXT NOT NULL REFERENCES attempts(id), request_id TEXT NOT NULL, response_json TEXT NOT NULL, PRIMARY KEY(attempt_id,request_id));
CREATE TABLE api_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
